import numpy as np, gzip, pickle
from scipy import ndimage as nd

def norm(img):
    """MNIST-style: crop to ink, scale longest side to 20px, center by mass in 28x28."""
    m = img > 0.1
    if not m.any(): return np.zeros((28,28), np.float32)
    ys, xs = np.where(m)
    c = img[ys.min():ys.max()+1, xs.min():xs.max()+1]
    h, w = c.shape
    s = 20.0 / max(h, w)
    nh, nw = max(1, round(h*s)), max(1, round(w*s))
    c = nd.zoom(c, (nh/h, nw/w), order=1)
    c = np.clip(c, 0, 1)
    out = np.zeros((28,28), np.float32)
    y0, x0 = (28-nh)//2, (28-nw)//2
    out[y0:y0+nh, x0:x0+nw] = c[:nh,:nw]
    cy, cx = nd.center_of_mass(out)
    out = nd.shift(out, (14-cy, 14-cx), order=1, mode='constant')
    return np.clip(out, 0, 1).astype(np.float32)

def augment(img, rng):
    a = np.deg2rad(rng.uniform(-14, 14)); sh = rng.uniform(-0.3, 0.3)
    sx, sy = rng.uniform(0.75, 1.25), rng.uniform(0.85, 1.15)
    M = np.array([[np.cos(a), -np.sin(a)], [np.sin(a), np.cos(a)]]) @ np.array([[1, sh], [0, 1]]) @ np.diag([sy, sx])
    Mi = np.linalg.inv(M); c = np.array([14, 14])
    big = np.zeros((40,40), np.float32); big[6:34,6:34] = img
    c = np.array([20,20])
    o = c - Mi @ c
    t = nd.affine_transform(big, Mi, offset=o, order=1)
    r = rng.random()
    if r < 0.3: t = nd.grey_dilation(t, size=(2,2))
    elif r < 0.45: t = nd.grey_erosion(t, size=(2,2)) if t.max() > 0.5 else t
    return norm(t)

def load():
    with gzip.open('/tmp/mnist.pkl.gz') as f:
        tr, va, te = pickle.load(f, encoding='latin1')
    return tr, va, te
__PB_EOF__
cat > 'tools/digits/train.py' <<'__PB_EOF__'
import numpy as np, warnings, time, json, base64
warnings.filterwarnings('ignore')
from prep import load, norm, augment
tr, va, te = load()
X = np.concatenate([tr[0], va[0]]).reshape(-1,28,28); Y = np.concatenate([tr[1], va[1]])
rng = np.random.default_rng(1)
t = time.time()
base = np.stack([norm(x) for x in X])
augs = [np.stack([augment(x, rng) for x in X]) for _ in range(3)]
Xa = np.concatenate([base] + augs).reshape(-1, 784); Ya = np.tile(Y, 4)
Xt = np.stack([norm(x) for x in te[0].reshape(-1,28,28)]).reshape(-1,784); Yt = te[1]
Xta = np.stack([augment(x, rng) for x in te[0].reshape(-1,28,28)]).reshape(-1,784)
print('data', Xa.shape, round(time.time()-t), 's', flush=True)

sizes = [784, 256, 128, 10]
W = [rng.normal(0, np.sqrt(2/sizes[i]), (sizes[i], sizes[i+1])).astype(np.float32) for i in range(3)]
B = [np.zeros(sizes[i+1], np.float32) for i in range(3)]
params = W + B
m = [np.zeros_like(p) for p in params]; v = [np.zeros_like(p) for p in params]
def fwd(x, train=False):
    acts = [x]; h = x
    for i in range(3):
        z = h @ W[i] + B[i]
        if i < 2:
            h = np.maximum(z, 0)
            if train:
                mask = (rng.random(h.shape) > 0.2) / 0.8; h = h * mask; acts.append((h, mask))
            else: acts.append((h, None))
        else: h = z
    return h, acts
def acc(X_, Y_): return (fwd(X_)[0].argmax(1) == Y_).mean()
lr, step, bs = 1e-3, 0, 128
for ep in range(14):
    if ep == 9: lr = 3e-4
    if ep == 12: lr = 1e-4
    idx = rng.permutation(len(Xa))
    for s in range(0, len(idx), bs):
        b = idx[s:s+bs]; x, y = Xa[b], Ya[b]
        out, acts = fwd(x, True)
        p = np.exp(out - out.max(1, keepdims=True)); p /= p.sum(1, keepdims=True)
        g = p; g[np.arange(len(y)), y] -= 1; g /= len(y)
        gW, gB = [None]*3, [None]*3
        for i in (2, 1, 0):
            hin = acts[i] if i == 0 else acts[i][0]
            gW[i] = hin.T @ g; gB[i] = g.sum(0)
            if i > 0:
                g = g @ W[i].T
                h, mask = acts[i]
                g = g * (h > 0) * mask
        step += 1
        for j, (pp, gg) in enumerate(zip(params, gW + gB)):
            m[j] = 0.9*m[j] + 0.1*gg; v[j] = 0.999*v[j] + 0.001*gg*gg
            mh = m[j]/(1-0.9**step); vh = v[j]/(1-0.999**step)
            pp -= lr * mh / (np.sqrt(vh) + 1e-8)
    print(f'ep {ep} test {acc(Xt,Yt):.4f} test-aug {acc(Xta,Yt):.4f} {round(time.time()-t)}s', flush=True)

# Export: int8 per-layer quantization, base64
layers = []
for i in range(3):
    s = float(np.abs(W[i]).max() / 127)
    q = np.round(W[i] / s).astype(np.int8)
    layers.append({'in': sizes[i], 'out': sizes[i+1], 'scale': s, 'w': base64.b64encode(q.tobytes()).decode(), 'b': [round(float(x), 5) for x in B[i]]})
    W[i] = q.astype(np.float32) * s
print('quantized test', acc(Xt, Yt), acc(Xta, Yt))
json.dump(layers, open('model.json', 'w'))
np.save('sample_x.npy', Xt[:50]); np.save('sample_out.npy', fwd(Xt[:50])[0])
__PB_EOF__
cat > 'tools/digits/recognizer.js' <<'__PB_EOF__'
// Handwritten number recognizer: groups strokes into digits, normalizes each
// MNIST-style (longest side 20px, centered by mass in 28x28), runs a small MLP.
(function (root) {
  let layers = null;
  function load(model) {
    layers = model.map(L => {
      const bin = atob(L.w), q = new Int8Array(bin.length);
      for (let i = 0; i < bin.length; i++) q[i] = (bin.charCodeAt(i) << 24) >> 24;
      const w = new Float32Array(q.length);
      for (let i = 0; i < q.length; i++) w[i] = q[i] * L.scale;
      return { inn: L.in, out: L.out, w, b: Float32Array.from(L.b) };
    });
  }
  function infer(x) { // x: Float32Array(784) in [0,1]
    let h = x;
    layers.forEach((L, li) => {
      const o = new Float32Array(L.out);
      for (let j = 0; j < L.out; j++) o[j] = L.b[j];
      for (let i = 0; i < L.inn; i++) {
        const v = h[i]; if (v === 0) continue;
        const row = i * L.out;
        for (let j = 0; j < L.out; j++) o[j] += v * L.w[row + j];
      }
      if (li < layers.length - 1) for (let j = 0; j < L.out; j++) if (o[j] < 0) o[j] = 0;
      h = o;
    });
    const m = Math.max(...h); let s = 0; const p = h.map(v => { const e = Math.exp(v - m); s += e; return e; });
    return Array.from(p, v => v / s);
  }

  function bbox(pts) {
    let a = Infinity, b = Infinity, c = -Infinity, d = -Infinity;
    for (const [x, y] of pts) { if (x < a) a = x; if (y < b) b = y; if (x > c) c = x; if (y > d) d = y; }
    return { x0: a, y0: b, x1: c, y1: d };
  }
  function groupStrokes(strokes) {
    const items = strokes.filter(s => s.length).map(s => ({ s, ...bbox(s) })).sort((p, q) => p.x0 - q.x0);
    const groups = [];
    for (const it of items) {
      const g = groups[groups.length - 1];
      if (g) {
        const ov = Math.min(g.x1, it.x1) - Math.max(g.x0, it.x0);
        const minW = Math.max(10, Math.min(g.x1 - g.x0, it.x1 - it.x0));
        const cx = (it.x0 + it.x1) / 2;
        if (ov > 0.3 * minW || (cx >= g.x0 && cx <= g.x1)) {
          g.strokes.push(it.s); g.x0 = Math.min(g.x0, it.x0); g.x1 = Math.max(g.x1, it.x1);
          g.y0 = Math.min(g.y0, it.y0); g.y1 = Math.max(g.y1, it.y1); continue;
        }
      }
      groups.push({ strokes: [it.s], x0: it.x0, y0: it.y0, x1: it.x1, y1: it.y1 });
    }
    return groups;
  }

  const R = 4, N = 28 * R; // render at 4x, then average down
  let cv = null;
  function draw(ctx, strokes, s, ox, oy) {
    ctx.clearRect(0, 0, N, N);
    ctx.strokeStyle = '#000'; ctx.fillStyle = '#000'; ctx.lineWidth = 2.6 * R; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    for (const st of strokes) {
      ctx.beginPath();
      st.forEach(([x, y], i) => { const X = x * s + ox, Y = y * s + oy; i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y); });
      if (st.length === 1) ctx.lineTo(st[0][0] * s + ox + 0.1, st[0][1] * s + oy);
      ctx.stroke();
    }
    return ctx.getImageData(0, 0, N, N).data;
  }
  function toInput(g) {
    if (!cv) { cv = document.createElement('canvas'); cv.width = cv.height = N; }
    const ctx = cv.getContext('2d', { willReadFrequently: true });
    const w = g.x1 - g.x0, h = g.y1 - g.y0;
    const s = (20 - 2.6) * R / Math.max(w, h, 1);
    let ox = N / 2 - (g.x0 + w / 2) * s, oy = N / 2 - (g.y0 + h / 2) * s;
    let d = draw(ctx, g.strokes, s, ox, oy);
    let m = 0, mx = 0, my = 0;
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) { const a = d[(y * N + x) * 4 + 3]; m += a; mx += a * x; my += a * y; }
    if (m > 0) { ox += N / 2 - mx / m; oy += N / 2 - my / m; d = draw(ctx, g.strokes, s, ox, oy); }
    const out = new Float32Array(784);
    for (let y = 0; y < 28; y++) for (let x = 0; x < 28; x++) {
      let a = 0;
      for (let dy = 0; dy < R; dy++) for (let dx = 0; dx < R; dx++) a += d[((y * R + dy) * N + x * R + dx) * 4 + 3];
      out[y * 28 + x] = a / (R * R * 255);
    }
    return out;
  }

  // strokes: array of arrays of [x, y]. Returns { text, digits: [{digit, confidence}] }.
  function recognize(strokes) {
    if (!layers) throw new Error('Digit model not loaded');
    const digits = groupStrokes(strokes).map(g => {
      const p = infer(toInput(g));
      let best = 0; p.forEach((v, i) => { if (v > p[best]) best = i; });
      return { digit: best, confidence: p[best] };
    });
    return { text: digits.map(d => d.digit).join(''), digits };
  }
  root.Digits = { load, recognize, infer, groupStrokes };
})(typeof window !== 'undefined' ? window : globalThis);
